create or replace function private.prepare_agreement_acceptance() returns trigger language plpgsql security definer set search_path='' as $$ declare agreement_body text; begin if length(trim(new.signed_name))<2 then raise exception 'Legal name is required'; end if; if coalesce((new.attestations->>'assume_risk')::boolean,false)=false or coalesce((new.attestations->>'indemnity')::boolean,false)=false or coalesce((new.attestations->>'insurance')::boolean,false)=false or coalesce((new.attestations->>'operating_rules')::boolean,false)=false then raise exception 'All material acknowledgments are required'; end if; select body_markdown into agreement_body from public.agreement_versions where id=new.agreement_version_id and status='active' and effective_at<=now(); if agreement_body is null then raise exception 'Agreement version is not active'; end if; new.user_id=(select auth.uid()); new.agreement_sha256=encode(extensions.digest(convert_to(agreement_body,'UTF8'),'sha256'),'hex'); new.accepted_at=now(); return new; end; $$;
revoke all on function private.prepare_agreement_acceptance() from public,anon,authenticated;
create trigger prepare_agreement_acceptance before insert on public.agreement_acceptances for each row execute function private.prepare_agreement_acceptance();
drop trigger booking_confirmation_guard on public.bookings;
create or replace function private.validate_booking_confirmation() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.status='confirmed' and (tg_op='INSERT' or old.status is distinct from 'confirmed') then if new.agreement_acceptance_id is null then raise exception 'Current renter agreement acceptance is required'; end if; if not exists(select 1 from public.agreement_acceptances a join public.agreement_versions v on v.id=a.agreement_version_id where a.id=new.agreement_acceptance_id and a.booking_id=new.id and a.business_id=new.renter_business_id and v.status='active' and v.effective_at<=now()) then raise exception 'Agreement acceptance is invalid or outdated'; end if; if exists(select 1 from public.kitchen_requirements kr where kr.kitchen_id=new.kitchen_id and kr.required and not exists(select 1 from public.credentials c where c.business_id=new.renter_business_id and c.credential_type=kr.credential_type and c.status='approved' and (c.expires_on is null or c.expires_on>=current_date))) then raise exception 'Required credential is missing, expired, or unapproved'; end if; new.risk_status='cleared'; end if; return new; end; $$;
revoke all on function private.validate_booking_confirmation() from public,anon,authenticated;
create trigger booking_confirmation_guard before insert or update of status on public.bookings for each row execute function private.validate_booking_confirmation();
